/** Mirror supported desktop model routing into an existing aiduCAT-managed DSH patch. */
import { randomUUID } from 'node:crypto';
import {
  closeSync, constants, fstatSync, lstatSync, openSync, readSync, realpathSync,
  renameSync, unlinkSync, writeFileSync, type Stats,
} from 'node:fs';
import { dirname, isAbsolute, join, parse, resolve, sep } from 'node:path';

const MIRRORED_IDS = ['agent-default-model', 'llm-pi-ai'] as const;
const PATCH = 'cordis.patch.yml';
const HEADER = [
  '# GENERATED by aiduCAT — do not edit by hand.',
  '# Mirrored from the desktop profile so Feishu follows the GUI model settings.',
  '# Source: $DSH_HOME/profiles/desktop/cordis.patch.yml',
  '# Regenerated automatically whenever that file changes.',
  '',
].join('\n');

export interface SyncResult {
  status: 'written' | 'unchanged' | 'source-missing' | 'source-invalid' | 'no-home'
    | 'target-unsafe' | 'target-missing' | 'target-unmanaged' | 'write-failed';
  source?: string;
  target?: string;
}

type InspectionStatus = Exclude<SyncResult['status'], 'written' | 'unchanged' | 'write-failed'>
  | 'in-sync' | 'stale';

/** The desktop serializer emits block-list rows beginning with an unquoted `id`. */
function parsePatchEntries(text: string): Map<string, string> | undefined {
  const entries = new Map<string, string>();
  let id: string | undefined;
  let lines: string[] = [];
  // Loader-patch documents also carry non-`id` top-level directives (insert
  // lists, disables, ...). They are irrelevant to the two routing rows we
  // mirror, so their whole indented block is skipped — the desktop profile
  // legitimately gains e.g. an MCP `insert:` alongside the model routing, and
  // that must not invalidate the source.
  let skippingBlock = false;
  for (const line of text.split(/\r?\n/)) {
    // Top-level comments are not properties of any row and can contain secrets.
    if (line.startsWith('#') || !line.trim()) continue;
    const indented = line.startsWith(' ');
    const top = !indented ? /^- id: ([A-Za-z0-9_][A-Za-z0-9_.-]*) *$/.exec(line)?.[1] : undefined;
    if (top) {
      if (entries.has(top) || top === id) return undefined;
      if (id) entries.set(id, lines.join('\n'));
      id = top;
      lines = [line];
      skippingBlock = false;
      continue;
    }
    if (indented) {
      if (skippingBlock) continue;
      if (id) { lines.push(line); continue; }
      return undefined;
    }
    // Top-level, not an `id` row: only a directive block header is acceptable;
    // anything else means the document is not in the shape we mirror.
    const directive = /^- ([A-Za-z][A-Za-z0-9_.-]*):/.exec(line)?.[1];
    if (directive) {
      if (id) entries.set(id, lines.join('\n'));
      id = undefined;
      lines = [];
      skippingBlock = true;
      continue;
    }
    return undefined;
  }
  if (id) entries.set(id, lines.join('\n'));
  return entries;
}

export function splitPatchEntries(text: string): Map<string, string> {
  return parsePatchEntries(text) ?? new Map();
}

// Deliberately not a general YAML parser: accept only the routing fields we know,
// in the desktop writer's block format. Re-emit validated rows, without comments,
// raw keys, headers, expressions, or other arbitrary source text.
const IDENT = /^[A-Za-z0-9_][A-Za-z0-9_.\/:@+-]*$/;
const KEY = /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/;
const LABEL = /^[\p{L}\p{N}][\p{L}\p{N}_. /()+@-]*$/u;
const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
const NUMBER = /^[1-9][0-9]*$/;
const EFFORTS = ['off', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max'];

function plainString(value: string, pattern: RegExp): boolean {
  return pattern.test(value) && !/^(?:null|true|false|~|[+-]?(?:\d|\.\d)[\d.e+-]*)$/i.test(value)
    && !/^(?:sk-|gh[pousr]_|xox[baprs]-|Bearer )/i.test(value);
}

function endpoint(value: string): boolean {
  if (!/^https?:\/\/[A-Za-z0-9.:[\]-]+(?:\/[A-Za-z0-9_./~%-]*)?$/.test(value)) return false;
  try {
    return Boolean(new URL(value).hostname);
  } catch {
    return false;
  }
}

type Row = { indent: number; text: string };

/** A cursor for the constrained block syntax; consumed rows form the output. */
class RoutingRows {
  private index = 0;
  constructor(private readonly rows: Row[]) {}

  get done(): boolean { return this.index === this.rows.length; }

  take(indent: number, expression: RegExp): string | undefined {
    const next = this.rows[this.index];
    if (next?.indent !== indent) return undefined;
    const matched = expression.exec(next.text);
    if (!matched) return undefined;
    this.index++;
    return matched[1] ?? '';
  }

  fields(indent: number, read: (key: string, value: string) => boolean): Set<string> | undefined {
    const seen = new Set<string>();
    while (this.rows[this.index]?.indent === indent) {
      const next = /^([A-Za-z0-9_][A-Za-z0-9_.-]*):(?: (.+))?$/.exec(this.rows[this.index]!.text);
      if (!next?.[1] || seen.has(next[1])) return undefined;
      this.index++;
      if (!read(next[1], next[2] ?? '')) return undefined;
      seen.add(next[1]);
    }
    return seen;
  }
}

function parseRoutingRows(block: string): { rows: RoutingRows; text: string } | undefined {
  const lines: string[] = [];
  const rows: Row[] = [];
  for (const line of block.split('\n')) {
    const withoutComment = line.replace(/(?:^| +)#.*$/, '').trimEnd();
    if (!withoutComment) continue;
    if (/[\x00-\x1f\x7f\u0085\u2028\u2029]/u.test(withoutComment)) return undefined;
    if (!lines.length) {
      lines.push(withoutComment);
      continue;
    }
    const match = /^( +)(\S.*)$/.exec(withoutComment);
    if (!match?.[1] || !match[2]) return undefined;
    rows.push({ indent: match[1].length, text: match[2] });
    lines.push(withoutComment);
  }
  return { rows: new RoutingRows(rows), text: lines.join('\n') };
}

function pluginConfig(rows: RoutingRows, name: string): boolean {
  const actual = rows.take(2, /^name: (.+)$/);
  return (actual === undefined || [name, `"${name}"`, `'${name}'`].includes(actual))
    && rows.take(2, /^config:$/) !== undefined;
}

function readModels(rows: RoutingRows): Set<string> | undefined {
  const models = new Set<string>();
  for (let id = rows.take(10, /^- id: (.+)$/); id !== undefined; id = rows.take(10, /^- id: (.+)$/)) {
    if (!plainString(id, IDENT) || models.has(id)) return undefined;
    models.add(id);
    const ok = rows.fields(12, (key, value) => {
      if (key === 'name') return plainString(value, LABEL);
      if (key === 'contextWindow' || key === 'maxTokens') return NUMBER.test(value);
      if (key === 'input' && !value) {
        let count = 0;
        while (rows.take(14, /^- (?:text|image|audio|video|document)$/) !== undefined) count++;
        return count > 0;
      }
      if (key === 'reasoningEfforts') {
        if (value === 'false') return true;
        if (value) return false;
        return Boolean(rows.fields(14, (effort, wire) => EFFORTS.includes(effort)
          && (effort === 'off' && ['', 'null', '""', "''"].includes(wire) || plainString(wire, IDENT)))?.size);
      }
      return false;
    });
    if (!ok) return undefined;
  }
  return models.size ? models : undefined;
}

function renderRouting(text: string): string | undefined {
  // A terminated document isn't proof of completeness, but a missing line
  // ending can indicate a truncate/rewrite caught in progress.
  if (!text.endsWith('\n')) return undefined;
  const entries = parsePatchEntries(text);
  const modelEntry = entries?.get('agent-default-model');
  const providerEntry = entries?.get('llm-pi-ai');
  if (!modelEntry || !providerEntry) return undefined;
  const selection = parseRoutingRows(modelEntry);
  const providerPatch = parseRoutingRows(providerEntry);
  if (!selection || !providerPatch || !pluginConfig(selection.rows, '@deepseek-ai/dsh-agent-default-model')
    || !pluginConfig(providerPatch.rows, '@deepseek-ai/dsh-llm-pi-ai')) return undefined;

  let provider = '';
  let model = '';
  const selected = selection.rows.fields(4, (key, value) => {
    if (!plainString(value, IDENT)) return false;
    if (key === 'provider') provider = value;
    else if (key === 'model') model = value;
    else if (key !== 'reasoningEffort') return false;
    return true;
  });
  const rows = providerPatch.rows;
  if (!selected || !selection.rows.done || !model || !provider
    || rows.take(4, /^providers:$/) === undefined) return undefined;
  let selectedModelDeclared = false;
  const routes = rows.fields(6, (route, value) => {
    if (!plainString(route, KEY) || route === '__proto__' || route === 'constructor' || value) return false;
    let models: Set<string> | undefined;
    const valid = rows.fields(8, (key, field) => {
      if (key === 'apiKeyEnv') return ENV_NAME.test(field);
      if (key === 'api') return plainString(field, IDENT);
      if (key === 'displayName') return plainString(field, LABEL);
      if (key === 'baseURL') return endpoint(field);
      if (key === 'models' && !field) return Boolean(models = readModels(rows));
      // Do not mirror arbitrary headers, credentials, or unsupported fields.
      return false;
    });
    if (route === provider) selectedModelDeclared = models?.has(model) ?? false;
    return Boolean(valid?.size);
  });
  return routes && rows.done && selectedModelDeclared
    ? `${HEADER}\n${selection.text}\n${providerPatch.text}\n` : undefined;
}

function safeProfile(profile: string): boolean {
  return /^[A-Za-z0-9][A-Za-z0-9_.-]*$/.test(profile) && !profile.endsWith('.')
    && !/^desktop$/i.test(profile) && !/^(?:con|prn|aux|nul|com[0-9]|lpt[0-9])(?:\.|$)/i.test(profile);
}

function missing(error: unknown): boolean {
  return (error as NodeJS.ErrnoException).code === 'ENOENT';
}

function samePath(left: string, right: string): boolean {
  return process.platform === 'win32' ? left.toLowerCase() === right.toLowerCase() : left === right;
}

function sameFile(left: Stats, right: Stats): boolean {
  return left.dev === right.dev && left.ino === right.ino;
}

function sameVersion(left: Stats, right: Stats): boolean {
  return sameFile(left, right) && left.size === right.size && left.mtimeMs === right.mtimeMs
    && left.ctimeMs === right.ctimeMs;
}

interface CheckedDirectory { path: string; stat: Stats }

function checkDirectories(path: string): CheckedDirectory[] {
  const root = parse(path).root;
  let parent = root;
  return [root, ...path.slice(root.length).split(sep).filter(Boolean)].map((part, index) => {
    if (index) parent = join(parent, part);
    const stat = lstatSync(parent);
    if (!stat.isDirectory() || stat.isSymbolicLink() || !samePath(realpathSync.native(parent), parent)) {
      throw new Error('Unsafe profile directory');
    }
    return { path: parent, stat };
  });
}

function directoriesStillMatch(checked: CheckedDirectory[]): boolean {
  const newest = checkDirectories(checked.at(-1)!.path);
  return checked.every(({ stat }, i) => sameFile(stat, newest[i]!.stat));
}

interface PatchSnapshot { text: string; stat: Stats; directories: CheckedDirectory[] }

function checkPatch(path: string): Stats {
  const stat = lstatSync(path);
  if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1 || stat.size > 1024 * 1024
    || !samePath(realpathSync.native(path), path)) throw new Error('Unsafe profile patch');
  return stat;
}

function readPatch(path: string): PatchSnapshot {
  const directories = checkDirectories(dirname(path));
  const before = checkPatch(path);
  const fd = openSync(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0));
  try {
    if (!sameVersion(before, fstatSync(fd))) throw new Error('Patch changed during open');
    const bytes = Buffer.alloc(before.size + 1);
    let length = 0;
    while (length < bytes.length) {
      const count = readSync(fd, bytes, length, bytes.length - length, null);
      if (!count) break;
      length += count;
    }
    if (length !== before.size || !sameVersion(before, fstatSync(fd))
      || !directoriesStillMatch(directories) || !sameVersion(before, checkPatch(path))) {
      throw new Error('Patch changed during read');
    }
    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes.subarray(0, length));
    return { text, stat: before, directories };
  } finally {
    closeSync(fd);
  }
}

/** What the mirror currently looks like, without changing any file. */
export interface DshRoutingInspection {
  status: InspectionStatus;
  source?: string;
  target?: string;
  profile?: string;
  sourceValid: boolean;
  /** Does the file have the aiduCAT signature? Use status to tell if it is writable. */
  targetGenerated: boolean;
  targetHasExtraEntries: boolean;
  inSync: boolean;
  targetMtime?: string;
}

function assess(configuredProfile?: string): { inspection: DshRoutingInspection; next?: string; target?: PatchSnapshot } {
  const home = process.env.DSH_HOME?.trim();
  const profile = (configuredProfile ?? process.env.AIDUCAT_DSH_PROFILE)?.trim() || 'headless';
  const inspection: DshRoutingInspection = {
    status: 'no-home', sourceValid: false, targetGenerated: false, inSync: false, targetHasExtraEntries: false,
  };
  if (!home) return { inspection };
  if (!isAbsolute(home) || !safeProfile(profile)) {
    inspection.status = 'target-unsafe';
    return { inspection };
  }
  const dir = join(resolve(home), 'profiles');
  const source = join(dir, 'desktop', PATCH);
  const targetPath = join(dir, profile, PATCH);
  Object.assign(inspection, { source, target: targetPath, profile });

  let next: string | undefined;
  let sourceStatus: 'source-missing' | 'source-invalid' = 'source-invalid';
  try {
    next = renderRouting(readPatch(source).text);
  } catch (error) {
    if (missing(error)) sourceStatus = 'source-missing';
  }
  inspection.sourceValid = next !== undefined;

  let target: PatchSnapshot | undefined;
  let targetStatus: 'target-unsafe' | 'target-missing' | 'target-unmanaged' | undefined;
  try {
    target = readPatch(targetPath);
    inspection.targetMtime = new Date(target.stat.mtimeMs).toISOString();
    const normalized = target.text.replace(/\r\n/g, '\n');
    inspection.targetGenerated = normalized.startsWith(`${HEADER}\n`);
    const entries = parsePatchEntries(normalized);
    inspection.targetHasExtraEntries = [...(entries?.keys() ?? [])].some(
      (id) => !MIRRORED_IDS.some((mirrored) => mirrored === id),
    );
    if (!inspection.targetGenerated || inspection.targetHasExtraEntries || renderRouting(normalized) !== normalized) {
      targetStatus = 'target-unmanaged';
    }
  } catch (error) {
    targetStatus = missing(error) ? 'target-missing' : 'target-unsafe';
  }
  inspection.inSync = !targetStatus && next !== undefined && target?.text === next;
  inspection.status = targetStatus === 'target-unsafe' ? targetStatus
    : !next ? sourceStatus : targetStatus ?? (inspection.inSync ? 'in-sync' : 'stale');
  return next && target ? { inspection, next, target } : { inspection };
}

export function inspectModelRouting(configuredProfile?: string): DshRoutingInspection {
  return assess(configuredProfile).inspection;
}

export function syncModelRoutingFromDesktop(configuredProfile?: string): SyncResult {
  const { inspection, next, target } = assess(configuredProfile);
  const paths = { ...(inspection.source ? { source: inspection.source } : {}),
    ...(inspection.target ? { target: inspection.target } : {}) };
  if (inspection.status === 'in-sync') return { status: 'unchanged', ...paths };
  if (inspection.status !== 'stale') return { status: inspection.status, ...paths };
  if (!inspection.target || !next || !target) return { status: 'write-failed', ...paths };

  // Exclusive creation avoids following a pre-existing temp symlink. Keeping
  // the temp file alongside the patch makes replacement atomic for DSH reads.
  const tmp = join(dirname(inspection.target), `.aiducat-${randomUUID()}.tmp`);
  let tempStat: Stats | undefined;
  const targetStillMatches = () => directoriesStillMatch(target.directories)
    && sameVersion(target.stat, checkPatch(inspection.target!));
  try {
    if (!targetStillMatches()) return { status: 'target-unsafe', ...paths };
    const fd = openSync(tmp, 'wx', 0o600);
    try {
      tempStat = fstatSync(fd);
      writeFileSync(fd, next, 'utf8');
    } finally {
      closeSync(fd);
    }
    if (!targetStillMatches() || !sameFile(tempStat, checkPatch(tmp))) {
      return { status: 'target-unsafe', ...paths };
    }
    renameSync(tmp, inspection.target);
    tempStat = undefined;
    return { status: 'written', ...paths };
  } catch {
    return { status: 'write-failed', ...paths };
  } finally {
    // Do not unlink through a changed directory chain or remove someone else's file.
    if (tempStat) {
      try {
        if (directoriesStillMatch(target.directories) && sameFile(tempStat, lstatSync(tmp))) unlinkSync(tmp);
      } catch { /* best-effort cleanup */ }
    }
  }
}
